using System.Linq;using UnityEngine;using UnityEditor;public static class InspectHumanModel{public static string Run(){var p=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Resources/Presentation/Human/HumanPlayer.prefab");var g=Object.Instantiate(p);var a=g.GetComponentInChildren<Animator>();string s="avatar="+a.avatar.name+" scale="+g.transform.localScale;foreach(var r in g.GetComponentsInChildren<Renderer>())s+="\n"+r.name+" "+r.bounds+" mats="+string.Join(",",r.sharedMaterials.Select(x=>x.name));foreach(var b in new[]{HumanBodyBones.Hips,HumanBodyBones.Chest,HumanBodyBones.Head,HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm,HumanBodyBones.LeftHand,HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot}){var t=a.GetBoneTransform(b);s+="\n"+b+"="+g.transform.InverseTransformPoint(t.position);}Object.DestroyImmediate(g);return s;}}
